function dailyFoundCount(){if(!game.daily)return 0;return [game.daily.lottery,game.daily.hair,game.daily.icecream,game.daily.kitty].filter(Boolean).length;}

function say(name, text, avatar = "🐶", callback) { game.dialogueQueue.push({ name, text, avatar, callback }); if (ui.dialogue.hidden) showNextDialogue(); }
function sayMany(lines, callback) { lines.forEach((line, index) => say(line[0], line[1], line[2], index === lines.length - 1 ? callback : null)); }
function showNextDialogue() { const next = game.dialogueQueue.shift(); if (!next) { ui.dialogue.hidden = true; return; } ui.speaker.textContent = next.name; ui.dialogueText.textContent = next.text; ui.avatar.textContent = next.avatar; ui.dialogue.hidden = false; game.dialogueCallback = next.callback || null; }
function advanceDialogue() { if (ui.dialogue.hidden) return; const callback = game.dialogueCallback; game.dialogueCallback = null; ui.dialogue.hidden = true; if (callback) callback(); showNextDialogue(); }

function worldPoint(event) { const rect = canvas.getBoundingClientRect(); return { x: (event.clientX - rect.left) * canvas.width / rect.width, y: (event.clientY - rect.top) * canvas.height / rect.height }; }
function setTarget(x, y) { player.tx = Math.max(55, Math.min(905, x)); player.ty = Math.max(285, Math.min(480, y)); }
function onPointer(event) { if(game.photoOpen){closeMirrorPhoto();return;} if (!ui.dialogue.hidden || !ui.ringPanel.hidden || !ui.letterPanel.hidden) return; const p = worldPoint(event); setTarget(p.x, p.y); const rect = canvas.getBoundingClientRect(); ui.tapMarker.style.left = `${event.clientX - rect.left}px`; ui.tapMarker.style.top = `${event.clientY - rect.top}px`; ui.tapMarker.style.display = "block"; ui.tapMarker.style.animation = "none"; void ui.tapMarker.offsetWidth; ui.tapMarker.style.animation = "marker .55s ease-out forwards"; }
function distance(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }

function initFishSchool(){
  const kinds=["fishBlue","fishGreen","fishOrange","fishPink","fishRed"];
  game.fish=Array.from({length:34},(_,i)=>({x:60+(i%17)*52+Math.random()*24,y:78+(i%6)*42+Math.random()*24,vx:36+Math.random()*30,vy:(Math.random()-.5)*18,kind:kinds[i%kinds.length],size:22+(i%4)*4,phase:Math.random()*Math.PI*2}));
}

function updateFishSchool(dt,time){
  if(!game.fish.length)return;
  const photoMode=game.stage===44||game.stage===45;
  const obstacle=photoMode?{x:(game.photoPose.jennyX+game.photoPose.herryX)/2,y:315}:{x:player.x,y:player.y-72};
  game.fish.forEach((fish,index)=>{
    let sepX=0,sepY=0,alignX=0,alignY=0,cohX=0,cohY=0,neighbors=0;
    game.fish.forEach((other,j)=>{if(index===j)return;const dx=other.x-fish.x,dy=other.y-fish.y,d=Math.hypot(dx,dy);if(d<105){neighbors++;alignX+=other.vx;alignY+=other.vy;cohX+=other.x;cohY+=other.y;if(d<34&&d>0){sepX-=dx/d;sepY-=dy/d;}}});
    if(neighbors){alignX=alignX/neighbors-fish.vx;alignY=alignY/neighbors-fish.vy;cohX=cohX/neighbors-fish.x;cohY=cohY/neighbors-fish.y;fish.vx+=(alignX*.045+cohX*.012+sepX*19)*dt;fish.vy+=(alignY*.045+cohY*.012+sepY*19)*dt;}
    const pdx=fish.x-obstacle.x,pdy=fish.y-obstacle.y,pd=Math.hypot(pdx,pdy);if(pd<125&&pd>0){const force=(125-pd)/125;fish.vx+=pdx/pd*520*force*dt;fish.vy+=pdy/pd*420*force*dt;}
    fish.vy+=Math.sin(time/650+fish.phase)*2.6*dt;if(fish.x<24)fish.vx+=55*dt;if(fish.x>936)fish.vx-=55*dt;if(fish.y<52)fish.vy+=48*dt;if(fish.y>318)fish.vy-=48*dt;
    const speed=Math.hypot(fish.vx,fish.vy),max=82;if(speed>max){fish.vx=fish.vx/speed*max;fish.vy=fish.vy/speed*max;}if(speed<24){fish.vx+=24*dt;}
    fish.x+=fish.vx*dt;fish.y+=fish.vy*dt;
  });
}

function updateDailyIceCream(dt,time){
  if(game.scene!=="daily"||!game.daily?.iceActive)return;const dx=player.x-game.daily.lastPlayerX;game.daily.lastPlayerX=player.x;game.daily.iceTilt+=(dx*.008+Math.sin(time/135)*.85*dt);game.daily.iceTilt*=Math.pow(.975,dt*60);game.daily.iceTilt=Math.max(-.78,Math.min(.78,game.daily.iceTilt));if(player.x>690){game.daily.iceActive=false;game.daily.icecream=true;game.daily.iceTilt=0;updateObjective();sayMany([["Jenny","十五块钱的超长冰淇淋，安全送达。","👧"],["花生","我只舔到了一点点空气！","🐶"]]);}
}

function updateDailyHerry(dt,time){
  if(game.scene!=="daily"||!game.daily?.hair)return;
  const trail=peanut.trail;const follow=trail[Math.max(0,trail.length-11)]||{x:player.x-52,y:player.y};
  const dx=follow.x-herry.x,dy=follow.y-herry.y,d=Math.hypot(dx,dy);herry.moving=d>5;
  if(herry.moving){const step=Math.min(d,178*dt);herry.x+=dx/d*step;herry.y+=dy/d*step;if(Math.abs(dx)>Math.abs(dy))herry.dir=dx<0?1:2;else herry.dir=dy<0?3:0;herry.frame=Math.floor(time/160)%4;}else herry.frame=1;
}

function updateCampus(dt,time){
  if(game.scene!=="campus"||!game.campus)return;const c=game.campus;
  if(game.stage===61&&c.timeStart&&time-c.timeStart>5600){c.timeDone=true;c.timeStart=0;game.stage=62;updateObjective();say("花生","天都黑了。你们两个认真起来，连我睡了几觉都不知道。","🐶");}
  if(c.area!=="court"||!c.ball)return;const b=c.ball;
  if(b.mode==="jennyShot"){const t=Math.min(1,(time-b.start)/1450);b.x=b.sx+(790-b.sx)*t;b.y=425-Math.sin(t*Math.PI)*225;if(t>=1){b.mode="landed";b.x=720;b.y=425;}}
  if(game.stage===64&&b.mode==="landed"){const dx=b.x-herry.x,dy=b.y-herry.y,d=Math.hypot(dx,dy);herry.moving=d>9;if(herry.moving){const step=Math.min(d,190*dt);herry.x+=dx/d*step;herry.y+=dy/d*step;herry.dir=dx<0?1:2;herry.frame=Math.floor(time/150)%4;}else{herry.frame=1;b.mode="held";game.stage=65;updateObjective();say("Herry","捡到了。现在换我投，你负责把球传回来。","👦",()=>startHerryShot());}}
  if(b.mode==="herryShot"){const t=Math.min(1,(time-b.start)/1350);b.x=b.sx+(805-b.sx)*t;b.y=422-Math.sin(t*Math.PI)*205;if(t>=1){b.mode="rolling";b.start=time;b.sx=790;b.x=790;b.y=426;game.stage=66;updateObjective();}}
  if(b.mode==="rolling"){const t=Math.min(1,(time-b.start)/1500);b.x=790+(320-790)*t;b.y=426+Math.sin(t*8*Math.PI)*7*(1-t);if(t>=1){b.mode="waiting";b.x=320;b.y=426;}}
  if(b.mode==="pass"){const t=Math.min(1,(time-b.start)/850);b.x=b.sx+(herry.x-b.sx)*t;b.y=420-Math.sin(t*Math.PI)*82;if(t>=1){if(c.rounds>=3){b.mode="done";c.couple=true;game.stage=67;updateObjective();sayMany([["花生","三次来回，判定为默契满分！","🐶"],["Jenny","旁边什么时候多了一台人生四格？","👧"]]);}else startHerryShot();}}
  if(game.stage===68&&c.photoStart&&time-c.photoStart>5200){c.photoDone=true;c.photoStart=0;game.stage=69;player.x=player.tx=420;player.y=player.ty=438;herry.x=520;herry.y=428;peanut.x=340;peanut.y=454;seedPeanutTrail();updateObjective();say("花生","最后一格笑出框了，但这一张最像你们。","🐶");}
}

function update(dt, time) {
  if(game.scene==="aquarium")updateFishSchool(dt,time);
  if(game.scene==="campus")updateCampus(dt,time);
  if (!game.running || game.photoOpen || !ui.dialogue.hidden || !ui.ringPanel.hidden || !ui.letterPanel.hidden || !ui.photoControls.hidden) return;
  let dx = 0, dy = 0;
  if (game.keys.has("ArrowLeft") || game.keys.has("a")) dx -= 1; if (game.keys.has("ArrowRight") || game.keys.has("d")) dx += 1; if (game.keys.has("ArrowUp") || game.keys.has("w")) dy -= 1; if (game.keys.has("ArrowDown") || game.keys.has("s")) dy += 1;
  if (dx || dy) { const length = Math.hypot(dx,dy); dx /= length; dy /= length; player.tx = player.x + dx * 24; player.ty = player.y + dy * 24; }
  const vx = player.tx - player.x, vy = player.ty - player.y, d = Math.hypot(vx,vy); player.moving = d > 2;
  if (player.moving) { const step = Math.min(d, player.speed * dt); player.x += vx / d * step; player.y += vy / d * step; if (Math.abs(vx) > Math.abs(vy)) player.dir = vx < 0 ? 1 : 2; else player.dir = vy < 0 ? 3 : 0; player.frame = Math.floor(time / 150) % 4; } else player.frame = 1;
  player.x = Math.max(55, Math.min(905, player.x)); player.y = Math.max(285, Math.min(480, player.y));
  updateDailyIceCream(dt,time);
  const newestTrailPoint = peanut.trail[peanut.trail.length - 1];
  if (!newestTrailPoint || Math.hypot(player.x - newestTrailPoint.x, player.y - newestTrailPoint.y) > 4) peanut.trail.push({x:player.x, y:player.y});
  if (peanut.trail.length > 120) peanut.trail.shift();
  updateDailyHerry(dt,time);
  const peanutLag=game.scene==="daily"&&game.daily?.hair?28:16;const follow = peanut.trail[Math.max(0, peanut.trail.length - peanutLag)] || {x:player.x - 65, y:player.y + 15}; const pdx = follow.x - peanut.x, pdy = follow.y - peanut.y, pd = Math.hypot(pdx,pdy); peanut.moving = pd > 4;
  if (peanut.moving) { const step = Math.min(pd, 150 * dt); peanut.x += pdx / pd * step; peanut.y += pdy / pd * step; if (Math.abs(pdx) > Math.abs(pdy)) peanut.dir = pdx < 0 ? 1 : 2; else peanut.dir = pdy < 0 ? 3 : 0; peanut.frame = Math.floor(time / 170) % 4; } else peanut.frame = 1;
  updateNearby();
}

