function drawCampus(time){if(game.campus?.area==="court")drawCampusCourt(time);else drawCampusCafe(time);}
function drawFilm(time){ctx.save();ctx.translate(480,335+Math.sin(time/250)*7);ctx.fillStyle="#f7c94a";ctx.fillRect(-30,-30,60,60);ctx.shadowColor="rgba(247,201,74,.75)";ctx.shadowBlur=18;ctx.drawImage(images.film,-23,-23,46,46);ctx.restore();}
function draw(time) { ctx.clearRect(0,0,960,540); if(game.scene==="projector") drawProjectorRoom(time); else if(game.scene==="hongdae")drawHongdae(time);else if(game.scene==="english")drawEnglishClass(time);else if(game.scene==="myeongdong")drawMyeongdong(time);else if(game.scene==="aquarium")drawAquarium(time);else if(game.scene==="daily")drawDailyStreet(time);else drawCampus(time);const photoComposition=(game.scene==="aquarium"&&(game.stage===44||game.stage===45))||(game.scene==="campus"&&game.stage===68);if(!photoComposition)[{type:"peanut",e:peanut,w:60,h:78},{type:"jenny",e:player,w:70,h:122}].sort((a,b)=>a.e.y-b.e.y).forEach(a=>drawSprite(images[a.type],a.e,a.w,a.h));if(game.scene==="myeongdong"&&game.stage>=32)drawPinkSkiCoat(player);if(!photoComposition&&game.scene==="campus"&&game.campus?.couple&&game.stage>=67)drawCoupleJacket(player,.9);drawSparkHeart(time); if(game.photoOpen)drawMirrorPhoto(time);if(time<game.cameraFlashUntil){const left=game.cameraFlashUntil-time;ctx.fillStyle=`rgba(255,255,255,${Math.min(1,left/150)})`;ctx.fillRect(0,0,960,540);} if(game.fade>0){ctx.fillStyle=`rgba(255,248,220,${Math.min(1,game.fade)})`;ctx.fillRect(0,0,960,540);} }
function loop(time) { const dt=Math.min(.034,(time-game.lastTime)/1000||0);game.lastTime=time;update(dt,time);if(game.fade>0){if(game.transition){game.fade+=dt*2.5;if(game.fade>=1){const cb=game.transition;game.transition=null;cb();game.fade=.99;}}else{game.fade-=dt*3;if(game.fade<=0)game.fade=0;}}draw(time);requestAnimationFrame(loop); }

ui.start.addEventListener("click",()=>startGame(false));ui.continue.addEventListener("click",()=>startGame(true));ui.restart.addEventListener("click",()=>startGame(false));canvas.addEventListener("pointerdown",onPointer);ui.action.addEventListener("click",()=>game.nearby?.action());ui.dialogue.addEventListener("click",advanceDialogue);
document.addEventListener("keydown",e=>{if(game.photoOpen&&(e.key===" "||e.key==="Enter")){closeMirrorPhoto();e.preventDefault();return;}if(["ArrowUp","ArrowDown","ArrowLeft","ArrowRight","w","a","s","d"].includes(e.key)){game.keys.add(e.key);e.preventDefault();}if((e.key===" "||e.key==="Enter")&&game.nearby&&!ui.action.hidden)game.nearby.action();});document.addEventListener("keyup",e=>game.keys.delete(e.key));
document.querySelectorAll("[data-ring]").forEach(button=>button.addEventListener("click",()=>chooseRing(button.dataset.ring)));document.querySelectorAll("[data-photo-move]").forEach(button=>button.addEventListener("click",()=>moveAquariumPose(button.dataset.photoMove)));ui.peanutPhotoButton.addEventListener("click",toggleAquariumPeanut);ui.aquariumShutter.addEventListener("click",takeAquariumPhoto);ui.aquariumDownload.addEventListener("click",downloadAquariumPhoto);ui.aquariumPhotoDone.addEventListener("click",finishAquariumPhoto);document.querySelector("#return-button").addEventListener("click",()=>{ui.letterPanel.hidden=true;game.stage=game.memorySix?12:game.memoryFive?11:game.memoryFour?10:game.memoryThree?8:game.memoryTwo?6:4;transitionTo(()=>setProjectorRoom(true));});document.querySelector("#sound-button").addEventListener("click",e=>{game.soundOn=!game.soundOn;e.currentTarget.textContent=game.soundOn?"♪":"×";});
loadImages().then(()=>{ui.loading.style.display="none"; ui.continue.hidden=!game.memoryOne; ui.start.textContent=game.memoryOne?"从头重玩":"进入放映室";}).catch(()=>{ui.loading.textContent="角色素材加载失败，请刷新重试。";});
